"""Markdown reports generated by `python -m dfwt build`."""
import collections
import os

from . import config

KEY_YEARS = (2025, 2030, 2035, 2040, 2050, 2070)


def _table(headers, rows):
    out = ["| " + " | ".join(headers) + " |", "|" + "|".join("---" for _ in headers) + "|"]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)


def _fmt(n):
    return f"{n:,}" if isinstance(n, int) else n


def write_all(ctx, nets, evals, findings):
    os.makedirs(config.path("reports"), exist_ok=True)
    write_results(ctx, nets, evals)
    write_validation(nets, findings)


def write_results(ctx, nets, evals):
    plan = evals["plan"]
    L = ["# Results", "",
         "Generated by `python -m dfwt build`. Do not edit by hand.", "",
         f"Demand source: **{ctx.od_source}** "
         + ("(LODES home-work flows)." if ctx.od_source == "lodes" else
            "(gravity model from 2020 census population and 2022 LODES jobs, fitted to a ~17 km mean "
            "commute; drop LODES OD into `data/raw/od_tracts.csv` to use real flows). Trust comparisons "
            "between plans and lines more than absolute counts."),
         "", "Definitions: *daily boardings* = weekday boardings on the modeled rail and BRT network "
         "(local buses are not modeled), estimated from the commute model with a mode-choice logit calibrated "
         "to today's ~80k rail boardings; see `config.json` -> `ridership`. Population and jobs grow by year "
         "(regional forecast plus development near new stations; `growth`), and peak drive times grow a "
         "little (`drive.congestion`). *Competitive commute* = transit door-to-door time no more than 1.3x the peak "
         "drive + 5 min (under 90 min, over 2 km). *Jobs in 45 min* = jobs reachable by transit in 45 "
         "minutes, averaged over every resident of the nine counties. *Coverage* = residents within "
         "800 m of a metro/BRT stop or 1.6 km of a commuter rail station. Costs are 2025 USD; shared "
         "track is charged once. All assumptions live in `config.json`.", ""]

    L += ["## Plan vs. scenarios", ""]
    hdr = ["Scenario"] + [f"{y}" for y in KEY_YEARS]
    for metric, label, f in (("daily_boardings", "Daily boardings (rail + BRT)", lambda v: f"{v / 1000:.0f}k"),
                             ("competitive_commutes", "Competitive commutes", lambda v: f"{v / 1000:.0f}k"),
                             ("jobs_45min", "Jobs reachable in 45 min (avg resident)", lambda v: f"{v / 1000:.1f}k"),
                             ("pop_covered_pct", "Residents near a station", lambda v: f"{v}%"),
                             ("capex_busd", "Capital spent, cumulative", lambda v: f"${v}B")):
        rows = []
        for key, ev in evals.items():
            by = {r["year"]: r for r in ev["years"]}
            rows.append([f"`{key}`"] + [f(by[y][metric]) for y in KEY_YEARS])
        L += [f"**{label}**", "", _table(hdr, rows), ""]

    if "v1_baseline" in evals:
        v1 = {r["year"]: r for r in evals["v1_baseline"]["years"]}
        v2 = {r["year"]: r for r in plan["years"]}
        rows = []
        for y in KEY_YEARS:
            dc = v2[y]["competitive_commutes"] - v1[y]["competitive_commutes"]
            dk = v2[y]["capex_busd"] - v1[y]["capex_busd"]
            rows.append([y, f"{dc:+,}", f"{v2[y]['jobs_45min'] - v1[y]['jobs_45min']:+,}", f"{dk:+.1f}"])
        L += ["## What the v2 changes bought", "",
              _table(["Year", "Competitive commutes vs v1", "Jobs in 45 min vs v1", "Capital vs v1 ($B)"], rows), ""]

    L += ["## Plan by year", ""]
    cols = ["year", "pop_m", "jobs_m", "stations", "lines", "km_metro", "km_brt", "km_commuter", "capex_busd",
            "pop_covered_pct", "competitive_commutes", "daily_boardings", "boardings_per_trip",
            "pnr_full_garages", "jobs_45min", "avg_transit_min"]
    L += [_table(cols, [[r[c] if c == "year" else _fmt(r[c]) for c in cols] for r in plan["years"]]), ""]

    L += ["## Proposed lines, by value", "",
          "*Value per $M* = competitive commutes lost if the line is removed (tested in its opening year "
          "and in 2070; the higher is used) divided by its capital cost. *Peak-hour load* assumes 10% of "
          "daily commute trips in the peak hour, 60% in the peak direction.", ""]
    prop = [r for r in plan["lines"] if r["status"] != "existing"]
    prop.sort(key=lambda r: -r["value_per_musd"] if isinstance(r.get("value_per_musd"), (int, float)) else 1)
    cols = ["name", "mode", "first_year", "km", "cost_musd", "marginal_at_opening", "marginal_final",
            "value_per_musd", "peak_hour_load", "capacity_used_pct"]
    L += [_table(cols, [[r.get(c, "") if c == "first_year" else _fmt(r.get(c, "")) for c in cols] for r in prop]), ""]
    L += ["## Existing lines (2070 loads)", ""]
    cols = ["name", "mode", "km", "headway_min", "daily_commuters_peak_link", "peak_hour_load", "capacity_used_pct"]
    L += [_table(cols, [[_fmt(r[c]) for c in cols] for r in plan["lines"] if r["status"] == "existing"]), ""]
    with open(config.path("reports", "RESULTS.md"), "w", encoding="utf-8") as f:
        f.write("\n".join(L))


def write_validation(nets, findings):
    L = ["# Validation", "", "Generated by `python -m dfwt build` (or `python -m dfwt validate -v`).", ""]
    for key, fs in findings.items():
        c = collections.Counter((f[0], f[1]) for f in fs)
        L += [f"## `{key}`", "", ", ".join(f"{sev} {code}: {n}" for (sev, code), n in sorted(c.items())) or "clean", ""]
        if key != "plan":
            continue
        for sev in ("error", "warn", "info"):
            items = [f for f in fs if f[0] == sev]
            if not items:
                continue
            L += [f"### {sev}", ""]
            L += [f"- **{code}** {line + ': ' if line else ''}{msg}" for _, code, line, msg in items]
            L += [""]
    with open(config.path("reports", "VALIDATION.md"), "w", encoding="utf-8") as f:
        f.write("\n".join(L))
